/*
 * demo-ui.c — GTK4 port.
 *
 * The original file was generated by Glade. The demo layout now lives
 * in data/demo.ui and is loaded with GtkBuilder.
 */

#ifdef HAVE_CONFIG_H
#  include <config.h>
#endif

#include <gtk/gtk.h>

#include "demo.h"
#include "demo-ui.h"
#include "glade-support.h"

GtkWidget*
create_demo_window (void)
{
    GtkBuilder* builder = glade_load_ui("demo.ui");
    GtkWidget* root;

    if(!builder)
        return NULL;

    root = GTK_WIDGET(gtk_builder_get_object(builder, "demo_root"));
    if(!root)
    {
        g_warning("luxeappearance: 'demo_root' not found in demo.ui");
        /* The builder is owned by the registry; drop only this failed
         * secondary builder so the main dialog remains valid. */
        glade_unregister_builder(builder);
        return NULL;
    }
    return root;
}
